source='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    colors = [c for c in counts if c != background]
    if not colors:
        return out
    foreground = max(colors, key=lambda c: counts[c])
    for r in range(h):
        cols = [c for c, value in enumerate(grid[r]) if value == foreground]
        for a, b in zip(cols, cols[1:]):
            for c in range(a + 1, b):
                if out[r][c] == background:
                    out[r][c] = 2
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == foreground]
        for a, b in zip(rows, rows[1:]):
            for r in range(a + 1, b):
                if out[r][c] == background:
                    out[r][c] = 2
    return out
'''
